1#HN:import { test, expect } from '@playwright/test';
2#KM:
3#SP:/**
4#VY: * E2E tests for the S04 UI architecture:
5#JM: * - Toolbar restructuring (essential buttons only, no layer checkboxes in toolbar)
6#HS: * - View menu dropdown (open/close, layer toggles, grid visibility)
7#PJ: * - Preferences modal (theme, units, grid, colors)
8#KQ: * - Unit switching and persistence
9#SV: * - Grid visibility vs grid snap separation
10#RB: * - Settings persistence across reload
11#MV: */
12#TX:
13#YP:test.describe('UI Architecture — Toolbar Structure', () => {
14#YZ:  test.beforeEach(async ({ page }) => {
15#PW:    // Clear settings to start fresh
16#KV:    await page.addInitScript(() => localStorage.removeItem('cypcb-settings'));
17#NW:    await page.goto('/');
18#SS:    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
19#HZ:  });
20#YQ:
21#TY:  test('essential toolbar buttons are visible', async ({ page }) => {
22#PH:    await expect(page.locator('#editor-toggle')).toBeVisible();
23#NX:    await expect(page.locator('#undo-btn')).toBeVisible();
24#KK:    await expect(page.locator('#redo-btn')).toBeVisible();
25#YP:    await expect(page.locator('#fit-btn')).toBeVisible();
26#MH:    await expect(page.locator('#view-menu-btn')).toBeVisible();
27#VB:    await expect(page.locator('#view-3d-btn')).toBeVisible();
28#QH:    await expect(page.locator('#theme-toggle')).toBeVisible();
29#NN:    await expect(page.locator('#prefs-btn')).toBeVisible();
30#XZ:    await expect(page.locator('#open-btn')).toBeVisible();
31#WV:  });
32#JQ:
33#YS:  test('layer checkboxes are NOT directly visible in toolbar (hidden in View dropdown)', async ({ page }) => {
34#JJ:    // The dropdown should be hidden by default
35#VW:    await expect(page.locator('#view-menu-dropdown')).toHaveClass(/hidden/);
36#KH:    // Layer checkboxes exist but are not visible (inside hidden dropdown)
37#PB:    await expect(page.locator('#layer-top')).not.toBeVisible();
