43#VV:test.describe('UI Architecture — View Menu', () => {
44#YZ:  test.beforeEach(async ({ page }) => {
45#KV:    await page.addInitScript(() => localStorage.removeItem('cypcb-settings'));
46#NW:    await page.goto('/');
47#SS:    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
48#NB:  });
49#BN:
50#VS:  test('View menu opens on click and closes on second click', async ({ page }) => {
51#WB:    const dropdown = page.locator('#view-menu-dropdown');
52#QQ:    await expect(dropdown).toHaveClass(/hidden/);
53#NB:
54#TK:    // Open
55#BZ:    await page.click('#view-menu-btn');
