57#WH:
58#TS:    // Close by clicking button again
59#BZ:    await page.click('#view-menu-btn');
60#QQ:    await expect(dropdown).toHaveClass(/hidden/);
61#WJ:  });
62#RJ:
63#NM:  test('View menu closes on Escape', async ({ page }) => {
64#WB:    const dropdown = page.locator('#view-menu-dropdown');
65#PZ:
66#BZ:    await page.click('#view-menu-btn');
