164#YZ:  test('unit switching to mil updates coords display', async ({ page }) => {
165#KY:    // Open Preferences
166#QY:    await page.click('#prefs-btn');
167#RS:    await expect(page.locator('#prefs-overlay')).not.toHaveClass(/hidden/);
168#BT:
169#BX:    // Switch units to mil
170#WR:    await page.selectOption('#prefs-units', 'mil');
171#NV:
172#MS:    // Close modal
173#NB:    await page.click('#prefs-close');
174#RT:
175#RY:    // Move mouse over canvas to trigger coords update
176#JT:    const canvas = page.locator('#pcb-canvas');
177#WM:    const box = await canvas.boundingBox();
178#BV:    if (box) {
179#ZJ:      await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
