206#ZK:test.describe('UI Architecture — Persistence', () => {
207#PQ:  test('unit setting persists across reload', async ({ page }) => {
208#NW:    await page.goto('/');
209#SS:    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
210#MR:    // Clear settings via evaluate (not addInitScript which re-runs on reload)
211#ZK:    await page.evaluate(() => localStorage.removeItem('cypcb-settings'));
212#HH:    await page.reload();
213#SS:    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
214#KZ:
215#JQ:    // Open Preferences, switch to mil
216#QY:    await page.click('#prefs-btn');
217#WR:    await page.selectOption('#prefs-units', 'mil');
218#NB:    await page.click('#prefs-close');
219#MH:
220#ZY:    // Verify it's set
221#TN:    const unitsBefore = await page.evaluate(() => (window as any).__settings?.units);
222#XM:    expect(unitsBefore).toBe('mil');
223#MK:
224#PZ:    // Reload page (no addInitScript to interfere)
225#HH:    await page.reload();
226#SS:    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
227#VQ:
228#ZY:    // Verify unit persisted
229#XB:    const unitsAfter = await page.evaluate(() => (window as any).__settings?.units);
230#WP:    expect(unitsAfter).toBe('mil');
231#ZN:  });
