236#ZK:    await page.evaluate(() => localStorage.removeItem('cypcb-settings'));
237#HH:    await page.reload();
238#SS:    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
239#HS:
240#HJ:    // Change top copper color via Preferences
241#QY:    await page.click('#prefs-btn');
242#RV:    const colorInput = page.locator('#prefs-color-top');
243#PP:    await colorInput.fill('#abcdef');
244#HB:    await colorInput.dispatchEvent('change');
245#NB:    await page.click('#prefs-close');
246#PT:
247#MT:    // Reload (settings should survive)
248#HH:    await page.reload();
249#SS:    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
