255#VZ:
256#NJ:  test('grid visibility vs grid snap are independent', async ({ page }) => {
257#KV:    await page.addInitScript(() => localStorage.removeItem('cypcb-settings'));
258#NW:    await page.goto('/');
259#SS:    await expect(page.locator('#status-text')).toContainText('Ready', { timeout: 15_000 });
260#ZQ:
261#HV:    // Toggle grid visibility off via View menu
262#BZ:    await page.click('#view-menu-btn');
