1#RS:/**
2#RW: * Project Manager — startup screen with templates, recent files, and file open.
3#SZ: *
4#RP: * Shows an overlay on app launch letting the user pick a template, open a recent
5#PY: * file, or import a .cypcb from disk. Dismissed automatically when a file loads.
6#ZT: *
7#YJ: * Debug surface: `window.__projectManager` exposes state for E2E tests.
8#BT: */
9#JT:
10#RP:import { getPreference, setPreference, type RecentFileEntry } from './settings';
11#NX:import { render, type RenderState } from './renderer';
12#JB:import { createViewport, fitBoard } from './viewport';
13#KP:import { createDefaultRenderConfig, buildPadNetMap } from './render-config';
14#HQ:import { createLayerVisibility } from './layers';
15#TZ:import type { BoardSnapshot } from './types';
16#VP:
17#BQ:// ---------------------------------------------------------------------------
18#TV:// Template descriptors (static, bundled in public/templates/)
19#VN:// ---------------------------------------------------------------------------
20#YQ:
21#PP:interface TemplateInfo {
22#XJ:  id: string;
23#MZ:  name: string;
24#MP:  description: string;
25#QJ:  file: string;
26#VX:}
27#JJ:
28#RH:const TEMPLATES: TemplateInfo[] = [
29#KB:  {
30#ZH:    id: 'blink',
31#NN:    name: 'Blink LED',
32#RJ:    description: '555 timer astable circuit — LED blinks at ~1.4 Hz',
33#ZS:    file: 'blink.cypcb',
34#WZ:  },
35#WH:  {
36#BV:    id: 'power-indicator',
37#YX:    name: 'Power Indicator',
38#KQ:    description: 'Simple LED power indicator with current-limiting resistor',
39#JW:    file: 'power-indicator.cypcb',
40#RN:  },
41#MT:  {
42#VY:    id: 'simple-psu',
43#WP:    name: 'Simple PSU',
44#WS:    description: '5V regulated power supply — 7805 with filter caps',
45#BW:    file: 'simple-psu.cypcb',
46#HW:  },
47#TT:];
48#BY:
49#RZ:// ---------------------------------------------------------------------------
50#ZW:// Blank project scaffold
51#QS:// ---------------------------------------------------------------------------
52#NM:
53#MQ:const BLANK_SCAFFOLD = `version 1
54#YJ:
55#SV:board untitled {
56#ZH:    size 50mm x 50mm
57#TH:    layers 2
58#VM:}
59#JY:`;
60#HQ:
61#BR:// ---------------------------------------------------------------------------
62#JX:// Callbacks from the host (main.ts)
63#TK:// ---------------------------------------------------------------------------
64#XZ:
65#QW:export interface ProjectManagerCallbacks {
66#QK:  onOpenFile: () => void;
67#NK:  onLoadTemplate: (source: string, name: string) => void;
68#JW:  onNewBlank: (source: string) => void;
69#YS:}
70#YY:
71#YM:// ---------------------------------------------------------------------------
72#KY:// Module state
73#RT:// ---------------------------------------------------------------------------
74#HQ:
75#KY:let overlay: HTMLElement | null = null;
76#TQ:let recentListEl: HTMLElement | null = null;
77#BN:let callbacks: ProjectManagerCallbacks | null = null;
78#SR:let visible = false;
79#BR:
80#SM:// ---------------------------------------------------------------------------
81#QT:// Public API
82#XN:// ---------------------------------------------------------------------------
83#YX:
84#KX:/**
85#BB: * Wire DOM event handlers on the project manager overlay.
86#HJ: * Call once after WASM init.
87#WJ: */
88#XX:export function initProjectManager(cb: ProjectManagerCallbacks): void {
89#PR:  callbacks = cb;
90#QT:
91#RQ:  overlay = document.getElementById('project-manager');
92#HM:  recentListEl = document.getElementById('pm-recent-list');
93#BX:
94#BX:  if (!overlay) {
95#PH:    console.warn('[ProjectManager] #project-manager element not found');
96#KV:    return;
97#PT:  }
98#BP:
99#RT:  // Template card clicks
100#PS:  const templateCards = overlay.querySelectorAll<HTMLElement>('[data-template]');
101#PN:  templateCards.forEach((card) => {
102#WV:    card.addEventListener('click', () => {
103#ZK:      const templateId = card.dataset.template!;
104#PZ:      handleTemplateClick(templateId);
105#RP:    });
106#NT:  });
107#TS:
108#KZ:  // Blank card
109#SY:  const blankCard = overlay.querySelector<HTMLElement>('[data-template-blank]');
110#MW:  if (blankCard) {
111#WS:    blankCard.addEventListener('click', () => {
112#RY:      callbacks?.onNewBlank(BLANK_SCAFFOLD);
113#ZW:    });
114#XT:  }
115#PV:
116#ZH:  // Open file button
117#JT:  const openBtn = overlay.querySelector<HTMLElement>('#pm-open-btn');
118#KV:  if (openBtn) {
119#NW:    openBtn.addEventListener('click', () => {
120#NT:      callbacks?.onOpenFile();
121#YM:    });
122#VR:  }
123#WY:
124#MT:  exposeDebugSurface();
125#JW:}
126#WV:
127#HJ:/**
128#PM: * Show the project manager overlay and populate dynamic content.
129#MQ: */
130#ZW:export function showProjectManager(): void {
131#HZ:  if (!overlay) return;
132#QZ:
133#BB:  populateRecentFiles();
134#KR:  overlay.classList.remove('hidden');
135#KH:  visible = true;
136#MT:  exposeDebugSurface();
137#QP:}
138#KK:
139#ZR:/**
140#NJ: * Hide the project manager overlay.
141#RV: */
142#NX:export function hideProjectManager(): void {
143#HZ:  if (!overlay) return;
144#BT:
145#BS:  overlay.classList.add('hidden');
146#SZ:  visible = false;
147#MT:  exposeDebugSurface();
148#YB:}
149#TJ:
150#TZ:/**
151#WJ: * Record a file open in the recent files list.
152#QT: * Generates a thumbnail from the current board state if a snapshot and canvas
153#YR: * context are available.
154#SV: *
155#XW: * @param name     Display name (filename)
156#TB: * @param snapshot Current board snapshot (optional, for thumbnail)
157#BK: * @param renderState Partial render state for thumbnail generation (optional)
158#KS: */
159#VT:export function addRecentFile(
160#QK:  name: string,
161#SH:  snapshot?: BoardSnapshot | null,
162#RY:  renderState?: Partial<RenderState> | null,
163#XJ:): void {
164#TJ:  const recentFiles = getPreference('recentFiles');
165#NX:
166#YX:  // Remove existing entry with same name
167#WH:  const filtered = recentFiles.filter((e) => e.name !== name);
168#BT:
169#BY:  let thumbnail: string | null = null;
170#RB:  if (snapshot && renderState) {
171#VN:    try {
172#WJ:      thumbnail = generateThumbnail(snapshot, renderState);
173#MQ:    } catch (e) {
