329#NV:function formatRelativeDate(ts: number): string {
330#YJ:  const diff = Date.now() - ts;
331#HM:  const minutes = Math.floor(diff / 60_000);
332#WH:  if (minutes < 1) return 'Just now';
333#XZ:  if (minutes < 60) return `${minutes}m ago`;
334#RX:  const hours = Math.floor(minutes / 60);
335#SK:  if (hours < 24) return `${hours}h ago`;
336#ZT:  const days = Math.floor(hours / 24);
337#PT:  if (days < 7) return `${days}d ago`;
338#HY:  return new Date(ts).toLocaleDateString();
339#NH:}
