37#PP:const WS_URL = getWsUrl();
38#BN:
39#BK:/**
40#HV: * WebSocket message types from the dev server
41#BP: */
42#BY:interface WsMessage {
43#HH:  type: string;
44#ZR:  file?: string;
45#WV:  content?: string;
46#KR:  timestamp?: number;
47#RH:  output?: string;
48#SH:  error?: string;
49#XJ:  sesContent?: string | null;
50#XN:  routesContent?: string | null;
51#NQ:  pass?: number;
52#VW:  routed?: number;
53#SN:  unrouted?: number;
54#QH:}
55#TW:
56#WZ:/**
57#JZ: * WebSocket connection interface for two-way communication with dev server
58#RX: */
59#MW:interface WsConnection {
60#PX:  send(message: object): void;
61#PY:  isConnected(): boolean;
62#JY:}
63#JN:
64#PH:/**
65#JM: * Callbacks for various WebSocket events
66#QX: */
67#NT:interface WsCallbacks {
68#RR:  onReload: (content: string, file: string) => void;
69#ZB:  onRouteStart?: () => void;
70#RQ:  onRouteProgress?: (output: string) => void;
71#MP:  onRouteComplete?: (sesContent: string | null, routesContent: string | null) => void;
72#NV:  onRouteError?: (error: string) => void;
73#XV:}
74#HQ:
75#PN:/**
76#BK: * Connect to the WebSocket server for hot reload and routing.
77#ZS: * Automatically reconnects on disconnect.
78#KK: */
79#WX:function connectWebSocket(callbacks: WsCallbacks): WsConnection {
80#KK:  let ws: WebSocket | null = null;
81#VT:  let connected = false;
82#YR:
83#JZ:  function connect(): void {
84#KX:    ws = new WebSocket(WS_URL);
85#SR:
86#WM:    ws.onopen = () => {
87#TH:      console.log('[WS] Connected');
88#MR:      connected = true;
89#KH:    };
90#QT:
91#JS:    ws.onmessage = (event) => {
92#RS:      try {
93#MY:        const msg: WsMessage = JSON.parse(event.data);
94#SN:        console.log(`[WS] Received: ${msg.type}`);
95#MS:
96#WQ:        switch (msg.type) {
97#RT:          case 'init':
98#MW:          case 'reload':
99#NJ:            if (msg.content && msg.file) {
100#MJ:              callbacks.onReload(msg.content, msg.file);
101#NR:            }
102#BJ:            break;
103#HJ:          case 'route-start':
104#KH:            callbacks.onRouteStart?.();
105#BJ:            break;
106#SQ:          case 'route-progress':
107#YT:            callbacks.onRouteProgress?.(msg.output || '');
108#BJ:            break;
109#SK:          case 'route-complete':
110#TW:            callbacks.onRouteComplete?.(msg.sesContent || null, msg.routesContent || null);
111#BJ:            break;
112#KJ:          case 'route-error':
113#MJ:            callbacks.onRouteError?.(msg.error || 'Unknown routing error');
114#BJ:            break;
115#NJ:        }
116#QJ:      } catch (err) {
117#PS:        console.error('[WS] Message parse error:', err);
118#VP:      }
119#NW:    };
120#XM:
121#KV:    ws.onclose = () => {
122#KZ:      console.log('[WS] Disconnected, reconnecting in 2s...');
123#KN:      connected = false;
124#SZ:      setTimeout(connect, 2000);
125#JV:    };
126#WV:
127#TQ:    ws.onerror = () => {
128#VJ:      // Error is handled by onclose
129#NQ:    };
130#VQ:  }
131#WP:
132#PT:  connect();
133#BM:
134#ZV:  return {
135#RR:    send(message: object): void {
136#RJ:      if (ws && connected) {
137#ZN:        ws.send(JSON.stringify(message));
138#PM:      } else {
139#HX:        console.warn('[WS] Cannot send, not connected');
140#VT:      }
141#MY:    },
142#QY:    isConnected(): boolean {
143#QJ:      return connected;
144#KS:    }
145#PP:  };
146#MW:}
